// Generated by scripts/build-sprites.py from plugin/assets/meatball.svg: the sprite.
// Its root attributes pick the pose: data-fill (normal/full/stuffed), data-mood
// (alert/hurt/sleep/busy/testing/pass/fail/deliver/celebrate), data-chomp, data-mouth, data-idle and data-roll.
export const MEATBALL = "<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" width="64" height="64" shape-rendering="crispEdges"><title>Meatball</title><style>
.v,.m-open,.mo,.fm,.xm{display:none}
svg:not([data-fill]) .v-normal,svg[data-fill="normal"] .v-normal,svg[data-fill="full"] .v-full,svg[data-fill="stuffed"] .v-stuffed{display:inline}
svg[data-mouth="open"] .m-open{display:inline}
svg[data-mouth="open"] .m-closed{display:none}
svg[data-chomp] .m-open{display:inline;animation:cA .36s steps(1) infinite}
svg[data-chomp] .m-closed{display:inline;animation:cB .36s steps(1) infinite}
@keyframes cA{0%{visibility:visible}50%{visibility:hidden}}
@keyframes cB{0%{visibility:hidden}50%{visibility:visible}}
svg[data-mood="alert"] .f-default,svg[data-mood="alert"] .mc-default{display:none}
svg[data-mood="alert"] .f-alert,svg[data-mood="alert"] .mc-alert,svg[data-mood="alert"] .x-alert{display:inline}
svg[data-mood="hurt"] .f-default,svg[data-mood="hurt"] .mc-default{display:none}
svg[data-mood="hurt"] .f-hurt,svg[data-mood="hurt"] .mc-hurt,svg[data-mood="hurt"] .x-hurt{display:inline}
svg[data-mood="sleep"] .f-default,svg[data-mood="sleep"] .mc-default{display:none}
svg[data-mood="sleep"] .f-sleep,svg[data-mood="sleep"] .mc-sleep,svg[data-mood="sleep"] .x-sleep{display:inline}
svg[data-mood="busy"] .f-default,svg[data-mood="busy"] .mc-default{display:none}
svg[data-mood="busy"] .f-busy,svg[data-mood="busy"] .mc-busy,svg[data-mood="busy"] .x-busy{display:inline}
svg[data-mood="testing"] .f-default,svg[data-mood="testing"] .mc-default{display:none}
svg[data-mood="testing"] .f-testing,svg[data-mood="testing"] .mc-testing,svg[data-mood="testing"] .x-testing{display:inline}
svg[data-mood="pass"] .f-default,svg[data-mood="pass"] .mc-default{display:none}
svg[data-mood="pass"] .f-pass,svg[data-mood="pass"] .mc-pass,svg[data-mood="pass"] .x-pass{display:inline}
svg[data-mood="fail"] .f-default,svg[data-mood="fail"] .mc-default{display:none}
